    pid_col = pid % BLOCK_SIZE
    pid_row = pid // BLOCK_SIZE

    offset = pid_row * N + pid_col
    val = tl.load(input_ptr + offset * stride_input, boundary_check=True)

    if approx_method == "none":
        res = val * tl.math.erf(val / sqrt2)
    elif approx_method == "tanh":
