        if row != max_idx:
            temp = tl.load(P + row * stride_p)
            tl.store(P + row * stride_p, tl.load(P + max_idx * stride_p))
            tl.store(P + max_idx * stride_p, temp)
            temp = tl.load(A + row * stride_a + col * stride_a, mask=col < N, other=0.0)
            tl.store(A + row * stride_a + col * stride_a, tl.load(A + max_idx * stride_a + col * stride_a, mask=col < N, other=0.0))
            tl.store(A + max_idx * stride_a + col * stride_a, temp)
    for i in range(col.size()):
        if i == 0:
            u_val = tl.load(A + row * stride_a + i * stride_a, mask=i < N, other=0.0)
            tl.store(U + row * stride_u + i * stride_u, u_val)
        else:
