@triton.jit
def polygamma_kernel(x_ptr, out_ptr, n, K_MAX: tl.constexpr, EPSILON: tl.constexpr, fact: tl.constexpr):
    pid = tl.program_id(0)
    x = tl.load(x_ptr + pid)
    sum_terms = 0.0
    for k in range(0, K_MAX):
        denom = x + k
        if denom < EPSILON:
            continue
        term = 1.0 / denom ** (n + 1)
        sum_terms += term
    sign = (-1) ** (n + 1)
    res = sign * fact * sum_terms
    tl.store(out_ptr + pid, res)

def polygamma(n, input, *, out=None):
    try:
        if out is None:
            out = torch.empty_like(input)
        fact = 1
        for i in range(1, n + 1):
            fact *= i
        N = input.numel()
        grid = lambda meta: (triton.cdiv(N, meta['BLOCK_SIZE']),)
        polygamma_kernel[grid](input, out, n, K_MAX=1000, EPSILON=1e-06, fact=fact)
        return out
    except Exception:
        pass

